(function() {
	'use strict';

	BX.namespace('BX.Grid');

	/**
	 * BX.Grid.Pagination
	 * @param {BX.Main.grid} parent
	 * @constructor
	 */
	BX.Grid.Pagination = function(parent)
	{
		this.parent = null;
		this.container = null;
		this.links = null;
		this.init(parent);
	};

	BX.Grid.Pagination.prototype = {
		init(parent)
		{
			this.parent = parent;
		},

		getParent()
		{
			return this.parent;
		},

		getContainer()
		{
			if (!this.container)
			{
				this.container = BX.Grid.Utils.getByClass(this.getParent().getContainer(), this.getParent().settings.get('classPagination'), true);
			}

			return this.container;
		},

		getLinks()
		{
			const self = this;
			const result = BX.Grid.Utils.getByTag(this.getContainer(), 'a');

			this.links = [];

			if (result)
			{
				this.links = result.map((current) => {
					return new BX.Grid.Element(current, self.getParent());
				});
			}

			return this.links;
		},

		getLink(node)
		{
			let result = null;
			let filter;

			if (BX.type.isDomNode(node))
			{
				filter = this.getLinks().filter((current) => {
					return node === current.getNode();
				});

				if (filter.length > 0)
				{
					result = filter[0];
				}
			}

			return result;
		},

		/**
		 * Gets the navigation query parameter of the currently opened page.
		 * The parameter is known only to the component which rendered the navigation,
		 * so it is taken from the links of the navigation itself. Both formats are
		 * supported: PAGEN_<N>=<page> of CDBResult and <id>=page-<page> of PageNavigation.
		 * The active page is rendered as a span without href and shows the number the user
		 * sees, which differs from the number in the url when the numbering is reversed.
		 * So the number for the url is found by a neighbouring link: in direct numbering
		 * its shown and url numbers are equal, in reversed ones their sum is the same
		 * for every page.
		 * @return {?object} {name: value}, or null when the url of the first page is enough
		 */
		getCurrentPageParams()
		{
			const activePage = this.getCurrentPage();
			if (!activePage || activePage <= 1)
			{
				return null;
			}

			const pairs = [...this.getContainer().querySelectorAll('a[href]')]
				.map((link) => ({
					shownPage: Number(link.textContent.trim()),
					param: this.parsePageParam(link.getAttribute('href')),
				}))
				.filter(({ shownPage, param }) => Number.isInteger(shownPage) && shownPage > 0 && param);

			if (pairs.length === 0)
			{
				return null;
			}

			// In reversed numbering the middle page shows the same number as in its url,
			// so the numbering is direct only when no link says otherwise.
			const reversedPair = pairs.find(({ shownPage, param }) => param.page !== shownPage);
			const pageParam = (reversedPair || pairs[0]).param;
			const page = reversedPair ? pageParam.page + reversedPair.shownPage - activePage : activePage;

			return page > 0 ? { [pageParam.name]: pageParam.format(page) } : null;
		},

		/**
		 * Gets the navigation parameter from the url of a navigation link.
		 * @param {?string} href
		 * @return {?{name: string, page: number, format: function(number): string}}
		 */
		parsePageParam(href)
		{
			if (!BX.type.isNotEmptyString(href) || !href.includes('?'))
			{
				return null;
			}

			const query = href.split('#')[0].slice(href.indexOf('?') + 1);
			for (const pair of query.split('&'))
			{
				const [name, value = ''] = pair.split('=');

				if (/^PAGEN_\d+$/.test(name) && /^\d+$/.test(value))
				{
					return { name, page: Number(value), format: (page) => String(page) };
				}

				const match = /^page-(\d+)(-size-\d+)?$/.exec(value);
				if (match)
				{
					const size = match[2] || '';

					return { name, page: Number(match[1]), format: (page) => `page-${page}${size}` };
				}
			}

			return null;
		},

		/**
		 * Gets number of the currently opened page as the user sees it.
		 * The active page is rendered as a span without href, so its number is read
		 * from the text of the active item.
		 * @return {?number}
		 */
		getCurrentPage()
		{
			const container = this.getContainer();
			if (!BX.type.isDomNode(container))
			{
				return null;
			}

			const active = container.querySelector('.main-ui-pagination-active');
			if (!active)
			{
				return null;
			}

			const page = parseInt(active.textContent.trim(), 10);

			return Number.isNaN(page) ? null : page;
		},
	};
})();
